BEGIN READ ONLY; SET LOCAL jit=off;
SELECT '002078.SZ:irr_scen' AS chart, count(*) FROM (SELECT v.scenario_name, x."口径", x."收益率（%）" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x("口径", "收益率（%）") ORDER BY v.sort, 2) checked;
SELECT '002078.SZ:irr_curve' AS chart, count(*) FROM (SELECT x.price AS "买入价", '隐含收益率' AS "系列", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS "收益率" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2) checked;
SELECT '002078.SZ:req_curve' AS chart, count(*) FROM (SELECT round((x.r * 100)::numeric, 1)::text || '%' AS "要求收益率", s.name AS "情景", round(vi_pv(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.r)::numeric, 2) AS "最高买入价", x.r, s.sort FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x UNION ALL SELECT round((x.r * 100)::numeric, 1)::text || '%', '市场价', round(cc.latest_price::numeric, 2), x.r, 99 FROM vi_model_base m JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x ORDER BY 4, 5) checked;
SELECT '002078.SZ:path' AS chart, count(*) FROM (SELECT p.year, x.item, round(x.amount::numeric, 1) AS amount FROM vi_projection p JOIN vi_model_base m ON m.id = p.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('归母净利润', p.np_parent), ('计划股息', p.dividend), ('FCFE', p.fcfe)) x(item, amount) WHERE p.is_base ORDER BY p.year, x.item) checked;
SELECT '002078.SZ:debt' AS chart, count(*) FROM (SELECT h.year::text AS year, '历史' AS kind, round(h.interest_debt::numeric, 0) AS debt FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' WHERE h.interest_debt IS NOT NULL UNION ALL SELECT f.year::text, '预测', round(fc.debt_close::numeric, 0) FROM vi_forecast_base f JOIN vi_forecast_calc fc USING (id) JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY year) checked;
SELECT '002078.SZ:hist_np' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' CROSS JOIN LATERAL (VALUES ('归母净利润', h.np_parent), ('分红总额', h.dividend_total)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '002078.SZ:hist_cash' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '002078.SZ:hist_quality' AS chart, count(*) FROM (SELECT h.year, x.item, round((x.v * 100)::numeric, 1) AS pct FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('ROE', hc.roe)) x(item, v) WHERE x.v IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '002078.SZ:hist_vol' AS chart, count(*) FROM (SELECT h.year, round(h.volume::numeric, CASE WHEN h.volume < 100 THEN 3 ELSE 0 END) AS "业务量" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' WHERE h.volume IS NOT NULL ORDER BY h.year) checked;
SELECT '002078.SZ:fit' AS chart, count(*) FROM (SELECT f.dimension AS "维度", f.score AS "评分" FROM vi_fit_score_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '002078.SZ' ORDER BY f.sort, f.id) checked;
SELECT '002078.SZ:moat' AS chart, count(*) FROM (SELECT m.code || ' ' || left(m.title, 14) AS "壁垒", CASE m.strength WHEN '强' THEN 3 WHEN '中' THEN 2 WHEN '弱' THEN 1 ELSE 0 END AS "强度", coalesce(m.verdict, '待验证') AS "判定" FROM vi_moat_base m JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' ORDER BY m.code) checked;
SELECT '002078.SZ:forces' AS chart, count(*) FROM (SELECT v.code || ' ' || left(v.participant, 12) AS "环节", v.force AS "五力", CASE v.power WHEN '强' THEN 3 WHEN '中' THEN 2 ELSE 1 END * CASE v.effect WHEN '有利' THEN 1 WHEN '不利' THEN -1 ELSE 0 END AS "影响" FROM vi_value_chain_base v JOIN vi_company_base co ON co.id = v.company_id AND co.code = '002078.SZ' ORDER BY v.code) checked;
SELECT '002078.SZ:peers' AS chart, count(*) FROM (SELECT c.name AS "对手", x.k AS "指标", round((x.v * 100)::numeric, 1) AS "%" FROM vi_competitor_base c JOIN vi_company_base co ON co.id = c.company_id AND co.code = '002078.SZ' CROSS JOIN LATERAL (VALUES ('付费率或渗透率', c.paying_rate), ('毛利率', c.gross_margin), ('增速', c.growth)) x(k, v) WHERE x.v IS NOT NULL UNION ALL SELECT co.name || '（本公司）', x.k, round((x.v * 100)::numeric, 1) FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('增速', hc.revenue_yoy)) x(k, v) WHERE x.v IS NOT NULL AND h.year = (SELECT max(h2.year) FROM vi_fin_history_base h2 WHERE h2.company_id = h.company_id) ORDER BY 1, 2) checked;
SELECT '002078.SZ:theses' AS chart, count(*) FROM (SELECT coalesce(t.status, '未裁决') AS "裁决", count(*) AS n FROM vi_thesis_base t JOIN vi_company_base co ON co.id = t.company_id AND co.code = '002078.SZ' GROUP BY 1 ORDER BY 2 DESC) checked;
SELECT '002078.SZ:quarter' AS chart, count(*) FROM (SELECT d.period, d.line_item, round((d.yoy * 100)::numeric, 1) AS "同比（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '002078.SZ' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL ORDER BY d.period_end, d.line_item) checked;
SELECT '002078.SZ:checks' AS chart, count(*) FROM (SELECT k.result, count(*) AS n FROM vi_check k JOIN vi_model_base m ON m.id = k.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' GROUP BY k.result ORDER BY k.result) checked;
SELECT '002078.SZ:facts' AS chart, count(*) FROM (SELECT f.verify_status, count(*) AS n FROM vi_fact_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '002078.SZ' GROUP BY f.verify_status ORDER BY n DESC) checked;
SELECT '002078.SZ:price' AS chart, count(*) FROM (SELECT o.obs_date, round((CASE WHEN co.price_fx_metric_id IS NULL THEN o.value ELSE o.value * fx.value END)::numeric, 2) AS "股价" FROM vi_obs_current o JOIN vi_company_base co ON co.price_metric_id = o.metric_id AND co.code = '002078.SZ' LEFT JOIN LATERAL (SELECT x.value FROM vi_obs_current x WHERE x.metric_id = co.price_fx_metric_id AND x.obs_date <= o.obs_date ORDER BY x.obs_date DESC LIMIT 1) fx ON true ORDER BY o.obs_date) checked;
SELECT '002078.SZ:rf' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'CGB10Y.CCDC' ORDER BY o.obs_date) checked;
SELECT '002078.SZ:pulp' AS chart, count(*) FROM (SELECT o.obs_date, mt.name AS "口径", o.value AS "价格" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code IN ('SP.SHFE.WIND', 'SP.SHFE.SINA') AND o.obs_date >= current_date - 730 ORDER BY o.obs_date, 2) checked;
SELECT '002078.SZ:gm_q' AS chart, count(*) FROM (SELECT d.period, d.value AS "毛利率（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '002078.SZ' WHERE d.line_item = '毛利率' ORDER BY d.period_end) checked;
SELECT '601668.SH:irr_scen' AS chart, count(*) FROM (SELECT v.scenario_name, x."口径", x."收益率（%）" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x("口径", "收益率（%）") ORDER BY v.sort, 2) checked;
SELECT '601668.SH:irr_curve' AS chart, count(*) FROM (SELECT x.price AS "买入价", '隐含收益率' AS "系列", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS "收益率" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2) checked;
SELECT '601668.SH:req_curve' AS chart, count(*) FROM (SELECT round((x.r * 100)::numeric, 1)::text || '%' AS "要求收益率", s.name AS "情景", round(vi_pv(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.r)::numeric, 2) AS "最高买入价", x.r, s.sort FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x UNION ALL SELECT round((x.r * 100)::numeric, 1)::text || '%', '市场价', round(cc.latest_price::numeric, 2), x.r, 99 FROM vi_model_base m JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x ORDER BY 4, 5) checked;
SELECT '601668.SH:path' AS chart, count(*) FROM (SELECT p.year, x.item, round(x.amount::numeric, 1) AS amount FROM vi_projection p JOIN vi_model_base m ON m.id = p.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('归母净利润', p.np_parent), ('计划股息', p.dividend), ('FCFE', p.fcfe)) x(item, amount) WHERE p.is_base ORDER BY p.year, x.item) checked;
SELECT '601668.SH:debt' AS chart, count(*) FROM (SELECT h.year::text AS year, '历史' AS kind, round(h.interest_debt::numeric, 0) AS debt FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' WHERE h.interest_debt IS NOT NULL UNION ALL SELECT f.year::text, '预测', round(fc.debt_close::numeric, 0) FROM vi_forecast_base f JOIN vi_forecast_calc fc USING (id) JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY year) checked;
SELECT '601668.SH:hist_np' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' CROSS JOIN LATERAL (VALUES ('归母净利润', h.np_parent), ('分红总额', h.dividend_total)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '601668.SH:hist_cash' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '601668.SH:hist_quality' AS chart, count(*) FROM (SELECT h.year, x.item, round((x.v * 100)::numeric, 1) AS pct FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('ROE', hc.roe)) x(item, v) WHERE x.v IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '601668.SH:hist_vol' AS chart, count(*) FROM (SELECT h.year, round(h.volume::numeric, CASE WHEN h.volume < 100 THEN 3 ELSE 0 END) AS "业务量" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' WHERE h.volume IS NOT NULL ORDER BY h.year) checked;
SELECT '601668.SH:fit' AS chart, count(*) FROM (SELECT f.dimension AS "维度", f.score AS "评分" FROM vi_fit_score_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '601668.SH' ORDER BY f.sort, f.id) checked;
SELECT '601668.SH:moat' AS chart, count(*) FROM (SELECT m.code || ' ' || left(m.title, 14) AS "壁垒", CASE m.strength WHEN '强' THEN 3 WHEN '中' THEN 2 WHEN '弱' THEN 1 ELSE 0 END AS "强度", coalesce(m.verdict, '待验证') AS "判定" FROM vi_moat_base m JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' ORDER BY m.code) checked;
SELECT '601668.SH:forces' AS chart, count(*) FROM (SELECT v.code || ' ' || left(v.participant, 12) AS "环节", v.force AS "五力", CASE v.power WHEN '强' THEN 3 WHEN '中' THEN 2 ELSE 1 END * CASE v.effect WHEN '有利' THEN 1 WHEN '不利' THEN -1 ELSE 0 END AS "影响" FROM vi_value_chain_base v JOIN vi_company_base co ON co.id = v.company_id AND co.code = '601668.SH' ORDER BY v.code) checked;
SELECT '601668.SH:peers' AS chart, count(*) FROM (SELECT c.name AS "对手", x.k AS "指标", round((x.v * 100)::numeric, 1) AS "%" FROM vi_competitor_base c JOIN vi_company_base co ON co.id = c.company_id AND co.code = '601668.SH' CROSS JOIN LATERAL (VALUES ('付费率或渗透率', c.paying_rate), ('毛利率', c.gross_margin), ('增速', c.growth)) x(k, v) WHERE x.v IS NOT NULL UNION ALL SELECT co.name || '（本公司）', x.k, round((x.v * 100)::numeric, 1) FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('增速', hc.revenue_yoy)) x(k, v) WHERE x.v IS NOT NULL AND h.year = (SELECT max(h2.year) FROM vi_fin_history_base h2 WHERE h2.company_id = h.company_id) ORDER BY 1, 2) checked;
SELECT '601668.SH:theses' AS chart, count(*) FROM (SELECT coalesce(t.status, '未裁决') AS "裁决", count(*) AS n FROM vi_thesis_base t JOIN vi_company_base co ON co.id = t.company_id AND co.code = '601668.SH' GROUP BY 1 ORDER BY 2 DESC) checked;
SELECT '601668.SH:quarter' AS chart, count(*) FROM (SELECT d.period, d.line_item, round((d.yoy * 100)::numeric, 1) AS "同比（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '601668.SH' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL ORDER BY d.period_end, d.line_item) checked;
SELECT '601668.SH:checks' AS chart, count(*) FROM (SELECT k.result, count(*) AS n FROM vi_check k JOIN vi_model_base m ON m.id = k.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' GROUP BY k.result ORDER BY k.result) checked;
SELECT '601668.SH:facts' AS chart, count(*) FROM (SELECT f.verify_status, count(*) AS n FROM vi_fact_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '601668.SH' GROUP BY f.verify_status ORDER BY n DESC) checked;
SELECT '601668.SH:price' AS chart, count(*) FROM (SELECT o.obs_date, round((CASE WHEN co.price_fx_metric_id IS NULL THEN o.value ELSE o.value * fx.value END)::numeric, 2) AS "股价" FROM vi_obs_current o JOIN vi_company_base co ON co.price_metric_id = o.metric_id AND co.code = '601668.SH' LEFT JOIN LATERAL (SELECT x.value FROM vi_obs_current x WHERE x.metric_id = co.price_fx_metric_id AND x.obs_date <= o.obs_date ORDER BY x.obs_date DESC LIMIT 1) fx ON true ORDER BY o.obs_date) checked;
SELECT '601668.SH:rf' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'CGB10Y.CCDC' ORDER BY o.obs_date) checked;
SELECT '601668.SH:conv' AS chart, count(*) FROM (SELECT h.year, round(hc.price::numeric, 3) AS "收入转化率" FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' WHERE hc.price IS NOT NULL ORDER BY h.year) checked;
SELECT '601668.SH:wc' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", round(d.value::numeric, 0) AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '601668.SH' WHERE d.period_kind = '全年' AND d.line_item IN ('应收账款＋合同资产', '应付票据及应付账款') UNION ALL SELECT h.year::text, '营业收入', round(h.revenue::numeric, 0) FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '601668.SH' WHERE h.year >= 2019 ORDER BY 1, 2) checked;
SELECT '601668.SH:imp' AS chart, count(*) FROM (SELECT d.period, round(d.value::numeric, 1) AS "减值" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '601668.SH' WHERE d.line_item = '资产及信用减值损失' AND d.period_kind = '全年' ORDER BY d.period_end) checked;
SELECT '01698.HK:irr_scen' AS chart, count(*) FROM (SELECT v.scenario_name, x."口径", x."收益率（%）" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x("口径", "收益率（%）") ORDER BY v.sort, 2) checked;
SELECT '01698.HK:irr_curve' AS chart, count(*) FROM (SELECT x.price AS "买入价", '隐含收益率' AS "系列", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS "收益率" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2) checked;
SELECT '01698.HK:req_curve' AS chart, count(*) FROM (SELECT round((x.r * 100)::numeric, 1)::text || '%' AS "要求收益率", s.name AS "情景", round(vi_pv(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.r)::numeric, 2) AS "最高买入价", x.r, s.sort FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x UNION ALL SELECT round((x.r * 100)::numeric, 1)::text || '%', '市场价', round(cc.latest_price::numeric, 2), x.r, 99 FROM vi_model_base m JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x ORDER BY 4, 5) checked;
SELECT '01698.HK:value' AS chart, count(*) FROM (SELECT v.scenario_name, round(v.value_today::numeric, 2) AS "今天每股价值" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY v.sort) checked;
SELECT '01698.HK:watch' AS chart, count(*) FROM (SELECT v.scenario_name, '今天价值' AS item, round(v.value_today::numeric, 2) AS price, v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '低档关注价', round(v.watch_low::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '高档关注价', round(v.watch_high::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '市场价', round(v.market_price::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY sort, item) checked;
SELECT '01698.HK:tv' AS chart, count(*) FROM (SELECT v.scenario_name, round(v.terminal_share::numeric, 4) AS "终值占比" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY v.sort) checked;
SELECT '01698.HK:path' AS chart, count(*) FROM (SELECT p.year, x.item, round(x.amount::numeric, 1) AS amount FROM vi_projection p JOIN vi_model_base m ON m.id = p.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('归母净利润', p.np_parent), ('计划股息', p.dividend), ('FCFE', p.fcfe)) x(item, amount) WHERE p.is_base ORDER BY p.year, x.item) checked;
SELECT '01698.HK:sens' AS chart, count(*) FROM (SELECT round((s.r * 100)::numeric, 2)::text || '%' AS r, 'g=' || round((s.g * 100)::numeric, 2)::text || '%' AS g, round(s.value_today::numeric, 2) AS value FROM vi_sensitivity s JOIN vi_model_base m ON m.id = s.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY s.r, s.g) checked;
SELECT '01698.HK:debt' AS chart, count(*) FROM (SELECT h.year::text AS year, '历史' AS kind, round(h.interest_debt::numeric, 0) AS debt FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' WHERE h.interest_debt IS NOT NULL UNION ALL SELECT f.year::text, '预测', round(fc.debt_close::numeric, 0) FROM vi_forecast_base f JOIN vi_forecast_calc fc USING (id) JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY year) checked;
SELECT '01698.HK:hist_np' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('归母净利润', h.np_parent), ('分红总额', h.dividend_total)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01698.HK:hist_cash' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01698.HK:hist_quality' AS chart, count(*) FROM (SELECT h.year, x.item, round((x.v * 100)::numeric, 1) AS pct FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('ROE', hc.roe)) x(item, v) WHERE x.v IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01698.HK:hist_vol' AS chart, count(*) FROM (SELECT h.year, round(h.volume::numeric, CASE WHEN h.volume < 100 THEN 3 ELSE 0 END) AS "业务量" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' WHERE h.volume IS NOT NULL ORDER BY h.year) checked;
SELECT '01698.HK:sotp_parts' AS chart, count(*) FROM (SELECT s.scenario_name AS "情景", x.k AS "部分", round((x.v / s.shares)::numeric, 2) AS "元/股", s.id, x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('核心业务', s.core_value, 1), ('成熟业务', s.mature_value, 2), ('成长业务', s.growth_value, 3), ('投入期业务', s.invest_value, 4), ('直接估值业务', s.direct_value, 4), ('可用净现金', s.usable_net_cash, 5), ('对外投资（折后）', s.investments, 6), ('少数股东与其他', s.minority_other, 7), ('合计', s.equity_value, 8)) x(k, v, o) WHERE x.v IS NOT NULL ORDER BY s.id, x.o) checked;
SELECT '01698.HK:sotp_bridge' AS chart, count(*) FROM (SELECT g.name AS "部分", round((g.value / s.shares)::numeric, 2) AS "元/股", 10 + coalesce(nullif(regexp_replace(g.code, '\D', '', 'g'), '')::int, 0) AS o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' JOIN vi_sotp_segment_val g ON g.scenario_id = s.id WHERE s.is_base UNION ALL SELECT '核心业务', round((s.core_value / s.shares)::numeric, 2), 1 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' WHERE s.is_base AND s.core_value IS NOT NULL UNION ALL SELECT x.k, round((x.v / s.shares)::numeric, 2), x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('可用净现金', s.usable_net_cash, 30), ('对外投资（折后）', s.investments, 31), ('少数股东与其他', s.minority_other, 32), ('每股价值', s.equity_value, 40), ('市场价', s.market_price * s.shares, 41)) x(k, v, o) WHERE s.is_base AND x.v IS NOT NULL ORDER BY 3) checked;
SELECT '01698.HK:sotp_grid' AS chart, count(*) FROM (SELECT x.m AS "倍数", s.scenario_name AS "系列", round(((coalesce(s.core_earnings, 0) * x.m + coalesce(s.mature_earn_pv, 0) * x.m + coalesce(s.mature_interim_pv, 0) + coalesce(s.growth_value, 0) + coalesce(s.invest_value, 0) + coalesce(s.direct_value, 0) + s.noncore) / s.shares)::numeric, 2) AS "每股价值", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN generate_series(4, 24, 2) x(m) UNION ALL SELECT x.m, '市场价', round(s.market_price::numeric, 2), 999 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN generate_series(4, 24, 2) x(m) WHERE s.is_base ORDER BY 1, 4) checked;
SELECT '01698.HK:sotp_mult' AS chart, count(*) FROM (SELECT s.scenario_name AS "情景", x.k AS "口径", round(x.v::numeric, 1) AS "倍", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('合理倍数', coalesce(s.multiple, s.mature_multiple)), ('市场隐含倍数', coalesce(s.implied_core_multiple, s.implied_mature_multiple))) x(k, v) ORDER BY s.id, 2) checked;
SELECT '01698.HK:fit' AS chart, count(*) FROM (SELECT f.dimension AS "维度", f.score AS "评分" FROM vi_fit_score_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '01698.HK' ORDER BY f.sort, f.id) checked;
SELECT '01698.HK:moat' AS chart, count(*) FROM (SELECT m.code || ' ' || left(m.title, 14) AS "壁垒", CASE m.strength WHEN '强' THEN 3 WHEN '中' THEN 2 WHEN '弱' THEN 1 ELSE 0 END AS "强度", coalesce(m.verdict, '待验证') AS "判定" FROM vi_moat_base m JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' ORDER BY m.code) checked;
SELECT '01698.HK:forces' AS chart, count(*) FROM (SELECT v.code || ' ' || left(v.participant, 12) AS "环节", v.force AS "五力", CASE v.power WHEN '强' THEN 3 WHEN '中' THEN 2 ELSE 1 END * CASE v.effect WHEN '有利' THEN 1 WHEN '不利' THEN -1 ELSE 0 END AS "影响" FROM vi_value_chain_base v JOIN vi_company_base co ON co.id = v.company_id AND co.code = '01698.HK' ORDER BY v.code) checked;
SELECT '01698.HK:peers' AS chart, count(*) FROM (SELECT c.name AS "对手", x.k AS "指标", round((x.v * 100)::numeric, 1) AS "%" FROM vi_competitor_base c JOIN vi_company_base co ON co.id = c.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('付费率或渗透率', c.paying_rate), ('毛利率', c.gross_margin), ('增速', c.growth)) x(k, v) WHERE x.v IS NOT NULL UNION ALL SELECT co.name || '（本公司）', x.k, round((x.v * 100)::numeric, 1) FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('增速', hc.revenue_yoy)) x(k, v) WHERE x.v IS NOT NULL AND h.year = (SELECT max(h2.year) FROM vi_fin_history_base h2 WHERE h2.company_id = h.company_id) ORDER BY 1, 2) checked;
SELECT '01698.HK:theses' AS chart, count(*) FROM (SELECT coalesce(t.status, '未裁决') AS "裁决", count(*) AS n FROM vi_thesis_base t JOIN vi_company_base co ON co.id = t.company_id AND co.code = '01698.HK' GROUP BY 1 ORDER BY 2 DESC) checked;
SELECT '01698.HK:quarter' AS chart, count(*) FROM (SELECT d.period, d.line_item, round((d.yoy * 100)::numeric, 1) AS "同比（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL ORDER BY d.period_end, d.line_item) checked;
SELECT '01698.HK:checks' AS chart, count(*) FROM (SELECT k.result, count(*) AS n FROM vi_check k JOIN vi_model_base m ON m.id = k.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01698.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' GROUP BY k.result ORDER BY k.result) checked;
SELECT '01698.HK:facts' AS chart, count(*) FROM (SELECT f.verify_status, count(*) AS n FROM vi_fact_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '01698.HK' GROUP BY f.verify_status ORDER BY n DESC) checked;
SELECT '01698.HK:price' AS chart, count(*) FROM (SELECT o.obs_date, round((CASE WHEN co.price_fx_metric_id IS NULL THEN o.value ELSE o.value * fx.value END)::numeric, 2) AS "股价" FROM vi_obs_current o JOIN vi_company_base co ON co.price_metric_id = o.metric_id AND co.code = '01698.HK' LEFT JOIN LATERAL (SELECT x.value FROM vi_obs_current x WHERE x.metric_id = co.price_fx_metric_id AND x.obs_date <= o.obs_date ORDER BY x.obs_date DESC LIMIT 1) fx ON true ORDER BY o.obs_date) checked;
SELECT '01698.HK:rf' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'CGB10Y.CCDC' ORDER BY o.obs_date) checked;
SELECT '01698.HK:rev_mix' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period_kind = '单季' AND d.line_item IN ('会员（订阅）收入', '非订阅音乐收入（广告、演出、周边）', '社交娱乐及其他收入') ORDER BY d.period_end, 2) checked;
SELECT '01698.HK:sub_yoy' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", round((d.yoy * 100)::numeric, 1) AS "同比（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL AND d.line_item IN ('会员（订阅）收入', '社交娱乐及其他收入', '营业收入') ORDER BY d.period_end, 2) checked;
SELECT '01698.HK:gm_q' AS chart, count(*) FROM (SELECT d.period, d.value AS "毛利率（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.line_item = '毛利率' ORDER BY d.period_end) checked;
SELECT '01698.HK:users' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "百万人" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.line_item IN ('在线音乐月活跃用户', '在线音乐付费用户') ORDER BY d.period_end, 2) checked;
SELECT '01698.HK:cash' AS chart, count(*) FROM (SELECT h.year::text AS year, x.item AS "项目", x.v AS "亿元" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('现金与定期存款', h.cash), ('带息负债', h.interest_debt)) x(item, v) WHERE h.year >= 2019 UNION ALL SELECT d.period, CASE WHEN d.line_item LIKE '现金%' THEN '现金与定期存款' ELSE '带息负债' END, d.value FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period = '2026Q2' AND (d.line_item LIKE '现金%' OR d.line_item LIKE '带息负债%') ORDER BY 1, 2) checked;
SELECT '01698.HK:payout' AS chart, count(*) FROM (SELECT h.year::text AS year, '历史' AS "口径", round((hc.payout * 100)::numeric, 1) AS "%" FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' WHERE h.year >= 2020 AND hc.payout IS NOT NULL UNION ALL SELECT p.year::text, '预测', round((p.payout * 100)::numeric, 1) FROM vi_projection p JOIN vi_company_base co ON co.id = p.company_id AND co.code = '01698.HK' JOIN vi_model_base m ON m.id = p.model_id AND m.status = '当前' WHERE p.is_base ORDER BY 1) checked;
SELECT '01698.HK:fx' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'HKDCNY' ORDER BY o.obs_date) checked;
SELECT '01810.HK:irr_scen' AS chart, count(*) FROM (SELECT v.scenario_name, x."口径", x."收益率（%）" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x("口径", "收益率（%）") ORDER BY v.sort, 2) checked;
SELECT '01810.HK:irr_curve' AS chart, count(*) FROM (SELECT x.price AS "买入价", '隐含收益率' AS "系列", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS "收益率" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2) checked;
SELECT '01810.HK:req_curve' AS chart, count(*) FROM (SELECT round((x.r * 100)::numeric, 1)::text || '%' AS "要求收益率", s.name AS "情景", round(vi_pv(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.r)::numeric, 2) AS "最高买入价", x.r, s.sort FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x UNION ALL SELECT round((x.r * 100)::numeric, 1)::text || '%', '市场价', round(cc.latest_price::numeric, 2), x.r, 99 FROM vi_model_base m JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN (SELECT generate_series(40, 100, 5) / 1000.0 AS r) x ORDER BY 4, 5) checked;
SELECT '01810.HK:value' AS chart, count(*) FROM (SELECT v.scenario_name, round(v.value_today::numeric, 2) AS "今天每股价值" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY v.sort) checked;
SELECT '01810.HK:watch' AS chart, count(*) FROM (SELECT v.scenario_name, '今天价值' AS item, round(v.value_today::numeric, 2) AS price, v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '低档关注价', round(v.watch_low::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '高档关注价', round(v.watch_high::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' UNION ALL SELECT v.scenario_name, '市场价', round(v.market_price::numeric, 2), v.sort FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY sort, item) checked;
SELECT '01810.HK:tv' AS chart, count(*) FROM (SELECT v.scenario_name, round(v.terminal_share::numeric, 4) AS "终值占比" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY v.sort) checked;
SELECT '01810.HK:path' AS chart, count(*) FROM (SELECT p.year, x.item, round(x.amount::numeric, 1) AS amount FROM vi_projection p JOIN vi_model_base m ON m.id = p.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('归母净利润', p.np_parent), ('计划股息', p.dividend), ('FCFE', p.fcfe)) x(item, amount) WHERE p.is_base ORDER BY p.year, x.item) checked;
SELECT '01810.HK:sens' AS chart, count(*) FROM (SELECT round((s.r * 100)::numeric, 2)::text || '%' AS r, 'g=' || round((s.g * 100)::numeric, 2)::text || '%' AS g, round(s.value_today::numeric, 2) AS value FROM vi_sensitivity s JOIN vi_model_base m ON m.id = s.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY s.r, s.g) checked;
SELECT '01810.HK:debt' AS chart, count(*) FROM (SELECT h.year::text AS year, '历史' AS kind, round(h.interest_debt::numeric, 0) AS debt FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' WHERE h.interest_debt IS NOT NULL UNION ALL SELECT f.year::text, '预测', round(fc.debt_close::numeric, 0) FROM vi_forecast_base f JOIN vi_forecast_calc fc USING (id) JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' ORDER BY year) checked;
SELECT '01810.HK:hist_np' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('归母净利润', h.np_parent), ('分红总额', h.dividend_total)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01810.HK:hist_cash' AS chart, count(*) FROM (SELECT h.year, x.item, x.amount FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01810.HK:hist_quality' AS chart, count(*) FROM (SELECT h.year, x.item, round((x.v * 100)::numeric, 1) AS pct FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('ROE', hc.roe)) x(item, v) WHERE x.v IS NOT NULL ORDER BY h.year, x.item) checked;
SELECT '01810.HK:hist_vol' AS chart, count(*) FROM (SELECT h.year, round(h.volume::numeric, CASE WHEN h.volume < 100 THEN 3 ELSE 0 END) AS "业务量" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' WHERE h.volume IS NOT NULL ORDER BY h.year) checked;
SELECT '01810.HK:sotp_parts' AS chart, count(*) FROM (SELECT s.scenario_name AS "情景", x.k AS "部分", round((x.v / s.shares)::numeric, 2) AS "元/股", s.id, x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('核心业务', s.core_value, 1), ('成熟业务', s.mature_value, 2), ('成长业务', s.growth_value, 3), ('投入期业务', s.invest_value, 4), ('直接估值业务', s.direct_value, 4), ('可用净现金', s.usable_net_cash, 5), ('对外投资（折后）', s.investments, 6), ('少数股东与其他', s.minority_other, 7), ('合计', s.equity_value, 8)) x(k, v, o) WHERE x.v IS NOT NULL ORDER BY s.id, x.o) checked;
SELECT '01810.HK:sotp_bridge' AS chart, count(*) FROM (SELECT g.name AS "部分", round((g.value / s.shares)::numeric, 2) AS "元/股", 10 + coalesce(nullif(regexp_replace(g.code, '\D', '', 'g'), '')::int, 0) AS o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' JOIN vi_sotp_segment_val g ON g.scenario_id = s.id WHERE s.is_base UNION ALL SELECT '核心业务', round((s.core_value / s.shares)::numeric, 2), 1 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' WHERE s.is_base AND s.core_value IS NOT NULL UNION ALL SELECT x.k, round((x.v / s.shares)::numeric, 2), x.o FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('可用净现金', s.usable_net_cash, 30), ('对外投资（折后）', s.investments, 31), ('少数股东与其他', s.minority_other, 32), ('每股价值', s.equity_value, 40), ('市场价', s.market_price * s.shares, 41)) x(k, v, o) WHERE s.is_base AND x.v IS NOT NULL ORDER BY 3) checked;
SELECT '01810.HK:sotp_grid' AS chart, count(*) FROM (SELECT x.m AS "倍数", s.scenario_name AS "系列", round(((coalesce(s.core_earnings, 0) * x.m + coalesce(s.mature_earn_pv, 0) * x.m + coalesce(s.mature_interim_pv, 0) + coalesce(s.growth_value, 0) + coalesce(s.invest_value, 0) + coalesce(s.direct_value, 0) + s.noncore) / s.shares)::numeric, 2) AS "每股价值", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN generate_series(4, 24, 2) x(m) UNION ALL SELECT x.m, '市场价', round(s.market_price::numeric, 2), 999 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN generate_series(4, 24, 2) x(m) WHERE s.is_base ORDER BY 1, 4) checked;
SELECT '01810.HK:sotp_mult' AS chart, count(*) FROM (SELECT s.scenario_name AS "情景", x.k AS "口径", round(x.v::numeric, 1) AS "倍", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('合理倍数', coalesce(s.multiple, s.mature_multiple)), ('市场隐含倍数', coalesce(s.implied_core_multiple, s.implied_mature_multiple))) x(k, v) ORDER BY s.id, 2) checked;
SELECT '01810.HK:fit' AS chart, count(*) FROM (SELECT f.dimension AS "维度", f.score AS "评分" FROM vi_fit_score_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '01810.HK' ORDER BY f.sort, f.id) checked;
SELECT '01810.HK:moat' AS chart, count(*) FROM (SELECT m.code || ' ' || left(m.title, 14) AS "壁垒", CASE m.strength WHEN '强' THEN 3 WHEN '中' THEN 2 WHEN '弱' THEN 1 ELSE 0 END AS "强度", coalesce(m.verdict, '待验证') AS "判定" FROM vi_moat_base m JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' ORDER BY m.code) checked;
SELECT '01810.HK:forces' AS chart, count(*) FROM (SELECT v.code || ' ' || left(v.participant, 12) AS "环节", v.force AS "五力", CASE v.power WHEN '强' THEN 3 WHEN '中' THEN 2 ELSE 1 END * CASE v.effect WHEN '有利' THEN 1 WHEN '不利' THEN -1 ELSE 0 END AS "影响" FROM vi_value_chain_base v JOIN vi_company_base co ON co.id = v.company_id AND co.code = '01810.HK' ORDER BY v.code) checked;
SELECT '01810.HK:peers' AS chart, count(*) FROM (SELECT c.name AS "对手", x.k AS "指标", round((x.v * 100)::numeric, 1) AS "%" FROM vi_competitor_base c JOIN vi_company_base co ON co.id = c.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('付费率或渗透率', c.paying_rate), ('毛利率', c.gross_margin), ('增速', c.growth)) x(k, v) WHERE x.v IS NOT NULL UNION ALL SELECT co.name || '（本公司）', x.k, round((x.v * 100)::numeric, 1) FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('毛利率', hc.gross_margin), ('增速', hc.revenue_yoy)) x(k, v) WHERE x.v IS NOT NULL AND h.year = (SELECT max(h2.year) FROM vi_fin_history_base h2 WHERE h2.company_id = h.company_id) ORDER BY 1, 2) checked;
SELECT '01810.HK:theses' AS chart, count(*) FROM (SELECT coalesce(t.status, '未裁决') AS "裁决", count(*) AS n FROM vi_thesis_base t JOIN vi_company_base co ON co.id = t.company_id AND co.code = '01810.HK' GROUP BY 1 ORDER BY 2 DESC) checked;
SELECT '01810.HK:quarter' AS chart, count(*) FROM (SELECT d.period, d.line_item, round((d.yoy * 100)::numeric, 1) AS "同比（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL ORDER BY d.period_end, d.line_item) checked;
SELECT '01810.HK:checks' AS chart, count(*) FROM (SELECT k.result, count(*) AS n FROM vi_check k JOIN vi_model_base m ON m.id = k.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '01810.HK' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' GROUP BY k.result ORDER BY k.result) checked;
SELECT '01810.HK:facts' AS chart, count(*) FROM (SELECT f.verify_status, count(*) AS n FROM vi_fact_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '01810.HK' GROUP BY f.verify_status ORDER BY n DESC) checked;
SELECT '01810.HK:price' AS chart, count(*) FROM (SELECT o.obs_date, round((CASE WHEN co.price_fx_metric_id IS NULL THEN o.value ELSE o.value * fx.value END)::numeric, 2) AS "股价" FROM vi_obs_current o JOIN vi_company_base co ON co.price_metric_id = o.metric_id AND co.code = '01810.HK' LEFT JOIN LATERAL (SELECT x.value FROM vi_obs_current x WHERE x.metric_id = co.price_fx_metric_id AND x.obs_date <= o.obs_date ORDER BY x.obs_date DESC LIMIT 1) fx ON true ORDER BY o.obs_date) checked;
SELECT '01810.HK:rf' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'CGB10Y.CCDC' ORDER BY o.obs_date) checked;
SELECT '01810.HK:seg_rev' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '单季' AND d.line_item IN ('手机×AIoT 分部收入', '智能电动汽车及AI分部收入') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:seg_profit' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '单季' AND d.line_item IN ('生态经营利润（推算）', '汽车及AI分部经营损益') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:eco_margin' AS chart, count(*) FROM (SELECT d.period, d.value AS "利润率（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item = '生态经营利润率（推算）' ORDER BY d.period_end, d.period_kind) checked;
SELECT '01810.HK:gm_lines' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "毛利率（%）" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '单季' AND d.line_item IN ('智能手机毛利率', 'IoT毛利率', '互联网服务毛利率', '汽车及AI分部毛利率') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:gm_lines_y' AS chart, count(*) FROM (SELECT d.period, CASE d.line_item WHEN '智能手机毛利率' THEN '手机毛利率' WHEN 'IoT毛利率' THEN 'IoT 毛利率' WHEN '互联网服务毛利率' THEN '互联网毛利率' ELSE '生态费用率' END AS "项目", d.value AS "%" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '全年' AND d.line_item IN ('智能手机毛利率', 'IoT毛利率', '互联网服务毛利率', '生态营业费用率（推算）') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:line_op' AS chart, count(*) FROM (SELECT d.period, CASE d.line_item WHEN '智能手机经营利润（分摊）' THEN '手机' WHEN 'AIoT经营利润（分摊）' THEN 'AIoT' ELSE '互联网' END AS "项目", d.value AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.period_kind = '全年' AND d.line_item IN ('智能手机经营利润（分摊）', 'AIoT经营利润（分摊）', '互联网服务经营利润（分摊）') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:ship' AS chart, count(*) FROM (SELECT d.period, d.value AS "百万台" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item = '智能手机出货量' ORDER BY d.period_end, d.period_kind) checked;
SELECT '01810.HK:asp' AS chart, count(*) FROM (SELECT d.period, d.value AS "元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item = '智能手机ASP' ORDER BY d.period_end) checked;
SELECT '01810.HK:ev' AS chart, count(*) FROM (SELECT d.period, d.value AS "辆" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item = '汽车交付量' AND d.period_kind = '单季' ORDER BY d.period_end) checked;
SELECT '01810.HK:mau' AS chart, count(*) FROM (SELECT d.period, d.value AS "百万人" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item IN ('全球月活跃用户（12 月）', '全球月活跃用户') ORDER BY d.period_end, d.period_kind) checked;
SELECT '01810.HK:cash_q' AS chart, count(*) FROM (SELECT d.period, d.line_item AS "项目", d.value AS "亿元" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01810.HK' WHERE d.line_item IN ('现金储备', '借款') ORDER BY d.period_end, 2) checked;
SELECT '01810.HK:fx' AS chart, count(*) FROM (SELECT o.obs_date, o.value AS "数值" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code = 'HKDCNY' ORDER BY o.obs_date) checked;
ROLLBACK;